/// Look up `name` (case-insensitively) in a sorted name/code table.
pub fn lookup(table: &[(&str, u8)], name: &str) -> Option<u8> {
    let name = name.to_ascii_lowercase();
    table
        .binary_search_by(|(k, _)| k.cmp(&name.as_str()))
        .ok()
        .map(|i| table[i].1)
}
